#include <stdio.h>

void merge(const int a[], int n, const int b[], int m, int out[]) {
    int i = 0, j = 0, k = 0;
    while (i < n && j < m) {
        out[k++] = a[i] <= b[j] ? a[i++] : b[j++];
    }
    while (i < n) out[k++] = a[i++];
    while (j < m) out[k++] = b[j++];
}

int main() {
    int a[] = {1, 5, 8};
    int b[] = {2, 3, 4, 20, 30};
    int out[8] = {0};
    merge(a, 3, b, 5, out);
    for (int i = 0; i < 8; i++) printf("%d ", out[i]);
    printf("\n");
    return 0;
}
